-- Repair only exact mojibake variants of known seed strings; preserve all IDs and account credentials.
-- Back up first. Do not run with mysql --force. Safe to re-run after a successful repair.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE encoding_repair_map (bad VARBINARY(2048) PRIMARY KEY, good TEXT CHARACTER SET utf8mb4);
-- DDL commits independently: temporarily accept both encodings while preserving a subject check.
ALTER TABLE admission DROP CHECK chk_admission_subject, ADD CONSTRAINT chk_admission_subject CHECK (subject_type IN (CONVERT(0xE789A9E79086E7B1BB USING utf8mb4), CONVERT(0xE58E86E58FB2E7B1BB USING utf8mb4), CONVERT(CONVERT(0xE789A9E79086E7B1BB USING latin1) USING utf8mb4), CONVERT(CONVERT(0xE58E86E58FB2E7B1BB USING latin1) USING utf8mb4)));
START TRANSACTION;
UPDATE school AS t JOIN encoding_repair_map AS m ON CAST(t.name AS BINARY) = m.bad SET t.name = m.good;
UPDATE school AS t JOIN encoding_repair_map AS m ON CAST(t.province AS BINARY) = m.bad SET t.province = m.good;
UPDATE school AS t JOIN encoding_repair_map AS m ON CAST(t.city AS BINARY) = m.bad SET t.city = m.good;
UPDATE school AS t JOIN encoding_repair_map AS m ON CAST(t.level AS BINARY) = m.bad SET t.level = m.good;
UPDATE school AS t JOIN encoding_repair_map AS m ON CAST(t.description AS BINARY) = m.bad SET t.description = m.good;
UPDATE major AS t JOIN encoding_repair_map AS m ON CAST(t.name AS BINARY) = m.bad SET t.name = m.good;
UPDATE major AS t JOIN encoding_repair_map AS m ON CAST(t.category AS BINARY) = m.bad SET t.category = m.good;
UPDATE major AS t JOIN encoding_repair_map AS m ON CAST(t.description AS BINARY) = m.bad SET t.description = m.good;
UPDATE admission AS t JOIN encoding_repair_map AS m ON CAST(t.province AS BINARY) = m.bad SET t.province = m.good;
UPDATE admission AS t JOIN encoding_repair_map AS m ON CAST(t.subject_type AS BINARY) = m.bad SET t.subject_type = m.good;
UPDATE sys_role AS t JOIN encoding_repair_map AS m ON CAST(t.role_name AS BINARY) = m.bad SET t.role_name = m.good;
UPDATE sys_permission AS t JOIN encoding_repair_map AS m ON CAST(t.permission_name AS BINARY) = m.bad SET t.permission_name = m.good;
UPDATE sys_user AS t JOIN encoding_repair_map AS m ON CAST(t.nickname AS BINARY) = m.bad SET t.nickname = m.good;
COMMIT;
ALTER TABLE admission DROP CHECK chk_admission_subject, ADD CONSTRAINT chk_admission_subject CHECK (subject_type IN (CONVERT(0xE789A9E79086E7B1BB USING utf8mb4), CONVERT(0xE58E86E58FB2E7B1BB USING utf8mb4)));
DROP TEMPORARY TABLE encoding_repair_map;
SELECT id, name, HEX(name) AS name_hex FROM school ORDER BY id LIMIT 3;
